//! `SystemOwnership::inspect` on Windows against the table that the .NET code produced
//! (`rust/tests/golden/ownership.json`, regenerated by `rust/tools/ownership-oracle`).
#![cfg(windows)]

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use serde_json::{Value, json};
use sermofur_core::ownership::{FileOwnership, SystemOwnership};
use uuid::Uuid;

/// A fresh folder, removed on drop.
struct TempRoot(PathBuf);

impl Drop for TempRoot {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn run(program: &str, args: &[&str]) {
    let out = Command::new(program).args(args).output().expect("runs");
    assert!(out.status.success(), "{program} {args:?} failed: {out:?}");
}

/// Prepares the entries of the oracle; false when the machine refuses symbolic links.
fn prepare(root: &Path) -> bool {
    let under = |relative: &str| root.join(relative);
    fs::create_dir(under("dir")).expect("dir");
    fs::write(under("file.txt"), "x").expect("file");
    let s = |p: PathBuf| p.to_str().expect("UTF-8 path").to_owned();
    run(
        "cmd",
        &[
            "/C",
            "mklink",
            "/J",
            &s(under("junction")),
            &s(under("dir")),
        ],
    );
    // The owner keeps full control but is denied the right to read the security descriptor.
    fs::create_dir(under("no-read-control")).expect("dir");
    let user = std::env::var("USERNAME").expect("USERNAME");
    run(
        "icacls",
        &[
            &s(under("no-read-control")),
            "/inheritance:r",
            "/grant:r",
            &format!("{user}:F"),
            "/deny",
            "*S-1-3-4:(RC)",
        ],
    );
    let links = [
        std::os::windows::fs::symlink_file(under("file.txt"), under("link-file")),
        std::os::windows::fs::symlink_dir(under("dir"), under("link-dir")),
        std::os::windows::fs::symlink_file(under("nowhere"), under("link-dangling")),
    ];
    links.iter().all(|made| {
        if let Err(error) = made {
            eprintln!("symlink creation refused ({error})");
        }
        made.is_ok()
    })
}

#[test]
fn inspect_matches_the_oracle() {
    let text = fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/golden/ownership.json"
    ))
    .expect("the golden file exists");
    let golden: Value = serde_json::from_str(&text).expect("valid JSON");
    assert_eq!(golden["os"], "windows");
    let root = TempRoot(std::env::temp_dir().join(format!("sermofur-owner-{}", Uuid::new_v4())));
    fs::create_dir_all(&root.0).expect("temp root");
    let links = prepare(&root.0);
    let allow_skip = std::env::var("SERMOFUR_ALLOW_SYMLINK_SKIP").is_ok_and(|v| v == "1");
    assert!(
        links || allow_skip,
        "symlink creation refused (SERMOFUR_ALLOW_SYMLINK_SKIP=1 allows it)"
    );
    let base = root.0.to_str().expect("UTF-8 path").to_owned();
    let system = std::env::var("SystemRoot").expect("SystemRoot");
    let sep = std::path::MAIN_SEPARATOR_STR;
    let path_of = |name: &str| -> String {
        let under = |relative: &str| format!("{base}{sep}{relative}");
        match name {
            "dir" => under("dir"),
            "dir_trailing_separator" => under("dir") + sep,
            "file" => under("file.txt"),
            "file_trailing_dot" => under("file.txt."),
            "file_trailing_separator" => under("file.txt") + sep,
            "absent" => under("absent"),
            "absent_parent" => under("absent/child"),
            "through_file" => under("file.txt/child"),
            "link_to_file" => under("link-file"),
            "link_to_dir" => under("link-dir"),
            "link_dangling" => under("link-dangling"),
            "junction" => under("junction"),
            "no_read_control" => under("no-read-control"),
            "system_dir" => system.clone(),
            "system_file" => format!(r"{system}\System32\kernel32.dll"),
            other => panic!("unknown case {other}"),
        }
    };
    let mut mismatches = Vec::new();
    let cases = golden["cases"].as_array().expect("cases");
    assert_eq!(cases.len(), 15);
    for case in cases {
        let name = case["name"].as_str().expect("a name");
        if !links && name.starts_with("link_") {
            continue;
        }
        let actual = match SystemOwnership.inspect(Path::new(&path_of(name))) {
            Ok(None) => json!({ "name": name, "status": null }),
            Ok(Some(s)) => json!({ "name": name, "status": {
                "isRegularFile": s.is_regular_file,
                "isDirectory": s.is_directory,
                "isOwnedByCurrentUser": s.is_owned_by_current_user,
            }}),
            Err(_) => json!({ "name": name, "error": true }),
        };
        if &actual != case {
            mismatches.push(format!("{name}: expected {case}, got {actual}"));
        }
    }
    // The folder must be removable although its owner cannot read its security descriptor.
    fs::remove_dir(root.0.join("no-read-control")).expect("DELETE is granted");
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}

/// Whether the session is elevated, decided apart from the action under test, as
/// `ElevatedWindowsFact`: the token holds the High Mandatory Level (S-1-16-12288).
fn elevated() -> bool {
    let out = Command::new("whoami")
        .arg("/groups")
        .output()
        .expect("whoami runs");
    assert!(out.status.success(), "whoami /groups failed: {out:?}");
    String::from_utf8_lossy(&out.stdout).contains("S-1-16-12288")
}

/// Port of `HardeningTests.RealOwnersAreCheckedOnWindows` at the level of `inspect`: SYSTEM is
/// foreign, Administrators belongs to an elevated user. Outside an elevated session it does
/// nothing, as `ElevatedWindowsFact`, except on GitHub Actions, where the runner is elevated and
/// a silent skip would hide the only end-to-end check of the token groups.
#[test]
fn real_owners_are_checked_when_elevated() {
    if !elevated() {
        assert!(
            std::env::var_os("GITHUB_ACTIONS").is_none(),
            "the CI runner must be elevated for this test"
        );
        eprintln!("not elevated: test skipped");
        return;
    }
    let root = TempRoot(std::env::temp_dir().join(format!("sermofur-owner-{}", Uuid::new_v4())));
    fs::create_dir_all(&root.0).expect("temp root");
    let path = root.0.to_str().expect("UTF-8 path").to_owned();
    let set_owner = |sid: &str| run("icacls", &[path.as_str(), "/setowner", sid]);
    let owned = || {
        SystemOwnership
            .inspect(&root.0)
            .expect("readable")
            .expect("present")
            .is_owned_by_current_user
    };
    set_owner("*S-1-5-18");
    assert!(!owned(), "SYSTEM is another account");
    set_owner("*S-1-5-32-544");
    assert!(owned(), "Administrators belongs to an elevated user");
}
